from functools import lru_cache
G={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
pieces=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if box<=G: pieces.append(('S',box,None))
  for miss in box:
   sh=box-{miss}
   if sh<=G: pieces.append(('L',sh,miss))
bycell={p:[] for p in G}
for x in pieces:
 for p in x[1]:bycell[p].append(x)
def solve(rem, parts):
 if not rem: yield parts;return
 p=min(rem,key=lambda q:sum(x[1]<=rem for x in bycell[q]))
 for x in bycell[p]:
  if x[1]<=rem:
   yield from solve(rem-x[1],parts+[x])
sol=list(solve(G,[]))
print('count',len(sol))
for s in sol:
 print([(k,sorted(v), miss) for k,v,miss in s])
